const items = $input.all();
const today = new Date().toISOString().split('T')[0];

const checkIns  = items.filter(i => i.json.Check_In  === today);
const checkOuts = items.filter(i => i.json.Check_Out === today);
const active    = items.filter(i => {
  const ci = i.json.Check_In;
  const co = i.json.Check_Out;
  return ci < today && co > today;
});

let msg = `🏠 *Airbnb Günlük Rapor — ${today}*\n\n`;

if (checkIns.length > 0) {
  msg += `✅ *Bugün Giriş (${checkIns.length})*\n`;
  checkIns.forEach(i => {
    msg += `  • ${i.json.Apartment} → ${i.json.Check_Out} çıkış (${i.json.Nights || '?'} gece)\n`;
  });
  msg += '\n';
}

if (checkOuts.length > 0) {
  msg += `🔑 *Bugün Çıkış (${checkOuts.length})*\n`;
  checkOuts.forEach(i => {
    msg += `  • ${i.json.Apartment} — temizlik gerekli\n`;
  });
  msg += '\n';
}

if (active.length > 0) {
  msg += `🛏️ *Dolu Daireler (${active.length})*\n`;
  active.forEach(i => {
    msg += `  • ${i.json.Apartment} → ${i.json.Check_Out} çıkış\n`;
  });
  msg += '\n';
}

if (checkIns.length === 0 && checkOuts.length === 0 && active.length === 0) {
  msg += '📭 Bugün aktif rezervasyon yok.\n';
}

msg += `\n_Toplam takipte: ${items.length} rezervasyon_`;

return [{ json: { message: msg, today, checkInsCount: checkIns.length, checkOutsCount: checkOuts.length } }];
